<template>
  <div class="appointment-grid-container flex h-screen flex-col bg-gray-100">
    <div class="flex-shrink-0 bg-white border-b border-gray-300 shadow-sm">
      <div class="px-6 py-4">
        <div class="flex items-center justify-between flex-wrap gap-4">
          <div class="flex items-center space-x-6">
            <h1 class="text-2xl font-semibold text-black">Appointments</h1>

            <div class="flex items-center">
              <Select
                v-model="selectedCompany"
                class="min-w-[240px]"
                variant="outline"
                placeholder="Select Company"
                :options="companies"
              />
            </div>

            <div class="flex items-center space-x-2">
              <Button variant="ghost" @click="goToPreviousDay">
                <FeatherIcon name="chevron-left" class="h-4 w-4 text-black" />
              </Button>

              <!-- A new date remounts the picker: frappe-ui keeps it open on Enter and on the old month. -->
              <DatePicker
                :key="selectedDate"
                v-model="selectedDate"
                variant="outline"
                placeholder="Select Date"
                class="min-w-[200px]"
              />

              <Button variant="ghost" @click="goToNextDay">
                <FeatherIcon name="chevron-right" class="h-4 w-4 text-black" />
              </Button>
            </div>
          </div>

          <div class="flex items-center gap-8">
            <DeskSearchBar />
            <AppointmentFilters />
            <Button
              icon-left="refresh-cw"
              label="Refresh"
              :loading="isLoadingDay"
              @click="refreshData"
            />
            <div
              v-if="canScrollLeft || canScrollRight"
              class="ml-4 flex items-center gap-4"
            >
              <Button
                size="lg"
                icon="arrow-left"
                label="Scroll practitioners left"
                :disabled="!canScrollLeft"
                @click="scrollPractitioners(-1)"
              />
              <Button
                size="lg"
                icon="arrow-right"
                label="Scroll practitioners right"
                :disabled="!canScrollRight"
                @click="scrollPractitioners(1)"
              />
            </div>
          </div>
        </div>
        <div class="mt-3 flex flex-wrap items-center justify-between gap-4">
          <ul
            class="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-gray-700"
            aria-label="Appointment status colours"
          >
            <li
              v-for="style in APPOINTMENT_STATUSES"
              :key="style.status"
              class="flex items-center gap-1.5"
            >
              <span
                class="h-3 w-3 rounded-sm border border-dotted"
                :class="style.card"
              />
              {{ style.label }}
            </li>
          </ul>
          <DefaultViewControls />
        </div>
      </div>
    </div>

    <div
      v-if="loadErrorMessage"
      role="alert"
      class="flex flex-shrink-0 items-center gap-3 border-b border-red-200 bg-red-50 px-6 py-2 text-sm text-red-800"
    >
      <span>Could not load this day: {{ loadErrorMessage }}</span>
      <Button label="Retry" :loading="isLoadingDay" @click="retryLoad" />
    </div>

    <div
      ref="scroller"
      class="grid-scroller"
      :class="{ 'opacity-60': isLoadingDay }"
      :aria-busy="isLoadingDay"
    >
      <div
        ref="grid"
        role="grid"
        aria-label="Appointments by time slot and practitioner"
        class="appointment-grid"
        :style="{
          '--columns': Math.max(practitioners.length, 1),
        }"
        @keydown="onGridKeydown"
        @focusin="onCellFocus"
      >
        <div role="row" class="contents">
          <div role="columnheader" class="corner-cell">
            <span class="text-sm font-semibold text-gray-600">Time Slots</span>
          </div>
          <div
            v-if="practitioners.length === 0"
            class="header-cell empty-header"
          >
            <span class="text-gray-500 text-sm">{{
              practitionerStore.isFetching
                ? "Loading practitioners..."
                : appointmentStore.hasFilters
                ? "No appointments match the filters"
                : "No practitioners found"
            }}</span>
          </div>
          <div
            v-for="practitioner in practitioners"
            :key="practitioner.name"
            role="columnheader"
            class="header-cell"
          >
            <PractitionerCard :practitioner="practitioner" />
          </div>
        </div>

        <div
          v-for="(slot, row) in slots"
          :key="slot.time"
          role="row"
          class="contents"
        >
          <div
            role="rowheader"
            class="time-cell"
            :class="{ 'current-time': row === currentSlotIndex }"
            :data-time-row="row"
          >
            <span class="text-sm font-bold text-gray-900">{{
              slot.time
            }}</span>
          </div>
          <SlotCell
            v-for="(practitioner, column) in practitioners"
            :key="`${slot.time}-${practitioner.name}`"
            :time-slot="slot"
            :practitioner="practitioner"
            :appointments="getAppointments(slot.time, practitioner.name)"
            :is-current="row === currentSlotIndex"
            :is-past="slot.timestamp < firstFutureTimestamp"
            :tabindex="
              activeCell.row === row && activeCell.column === column ? 0 : -1
            "
            :data-row="row"
            :data-column="column"
            @view="viewAppointment"
            @create="createAppointment"
          />
        </div>
      </div>
    </div>

    <AppointmentDialog
      v-model:show-dialog="showAppointmentDialog"
      :time-slot="selectedTimeSlot"
      :practitioner-data="selectedPractitioner"
      :mode="dialogMode"
      :app-data="selectedAppointmentData"
      :company="selectedCompany"
      @appointment-created="handleAppointmentCreated"
      @close-dialog="closeAppointmentDialog"
      @edit-appointment="handleEditAppointment"
      @mode-changed="handleModeChanged"
    />
  </div>
</template>

<script setup>
import { onMounted, onUnmounted, computed, ref, nextTick, watch } from "vue";
import { call } from "frappe-ui";
import { useSocket } from "@/socket";
// All Frappe UI components are now globally available from main.js
import { useAppointmentStore } from "@/data/appointment";
import { usePractitionerStore } from "@/data/practitioner";
import { useDateStore } from "@/data/date";
import { useRoute, useRouter } from "vue-router";
import {
  clamp,
  until,
  useNow,
  useResizeObserver,
  useDebounceFn,
  useScroll,
  watchDebounced,
} from "@vueuse/core";
import PractitionerCard from "./PractitionerCard.vue";
import SlotCell from "./SlotCell.vue";
import DefaultViewControls from "./DefaultViewControls.vue";
import { APPOINTMENT_STATUSES } from "./appointmentStatus";
import AppointmentDialog from "./AppointmentDialog.vue";
import AppointmentFilters from "./AppointmentFilters.vue";
import DeskSearchBar from "@/components/DeskSearchBar.vue";
import { getMatchedGrid } from "@/data/appointmentFilters";
import { serverErrorText, useToast } from "@/composables/useToast";

const appointmentStore = useAppointmentStore();
const practitionerStore = usePractitionerStore();
const dateStore = useDateStore();
const { notifications } = useToast();
const socket = useSocket();
const route = useRoute();
const router = useRouter();

const scroller = ref(null);
const grid = ref(null);

// State
const selectedCompany = ref("");
const selectedDate = computed({
  get: () => dateStore.selectedDate,
  set: (date) => date && dateStore.setSelectedDate(date),
});
const companies = ref([]);
const slotDurations = ref({});
const companyError = ref(null);

// Simple appointment dialog state
const showAppointmentDialog = ref(false);
const selectedTimeSlot = ref("");
const selectedPractitioner = ref(null);
const dialogMode = ref("create");
const selectedAppointmentData = ref({});

const { arrivedState, measure } = useScroll(scroller);
useResizeObserver([scroller, grid], () => measure());
const canScrollLeft = computed(() => !arrivedState.left);
const canScrollRight = computed(() => !arrivedState.right);
const activeCell = ref({ row: 0, column: 0 });

const now = useNow({ interval: 60_000 });
const nowTime = computed(() => now.value.getTime());

// While an appointment filter is on, only rows and columns holding a match are shown, so results need no scrolling.
const shownGrid = computed(() =>
  appointmentStore.hasFilters
    ? getMatchedGrid(
        dateStore.timeSlots,
        practitionerStore.filteredPractitioners,
        appointmentStore.appointmentsBySlot
      )
    : {
        slots: dateStore.timeSlots,
        practitioners: practitionerStore.filteredPractitioners,
      }
);
const slots = computed(() => shownGrid.value.slots);
const practitioners = computed(() => shownGrid.value.practitioners);

const isLoadingDay = computed(
  () => practitionerStore.isFetching || appointmentStore.isFetching
);
const loadErrorMessage = computed(
  () =>
    companyError.value ||
    practitionerStore.loadError ||
    appointmentStore.loadError
);

const loadDay = () =>
  appointmentStore.loadDay(selectedCompany.value, dateStore.selectedDate);

onMounted(() => {
  fetchUserCompanies();
  if (socket?.connected) subscribeToAppointments();
  socket?.on("connect", subscribeToAppointments);
  socket?.on("patient_appointment_update", onAppointmentUpdate);
  socket?.io.on("reconnect", loadDay);
  scrollToCurrentSlot();
});

onUnmounted(() => {
  socket?.off("connect", subscribeToAppointments);
  socket?.off("patient_appointment_update", onAppointmentUpdate);
  socket?.io.off("reconnect", loadDay);
  socket?.emit("doctype_unsubscribe", "Patient Appointment");
});

// The only trigger that loads a day. The debounce collapses fast date clicks into one load.
// The server lists practitioners by status, so a status change loads the day again.
watchDebounced(
  () => [
    selectedCompany.value,
    dateStore.selectedDate,
    practitionerStore.filters.practitioner_status,
  ],
  loadDay,
  { debounce: 150, immediate: true }
);

watch(selectedCompany, (company) => {
  if (company) dateStore.slotDuration = slotDurations.value[company];
});

watch(
  () => dateStore.timeSlots,
  () => scrollToCurrentSlot()
);

// Filtered results start at the top left; clearing returns to the current time.
watch(
  () => appointmentStore.hasFilters,
  (hasFilters) =>
    hasFilters
      ? scroller.value?.scrollTo({ top: 0, left: 0 })
      : scrollToCurrentSlot()
);

// Keep one cell reachable by Tab when the rows or columns shrink.
watch([slots, practitioners], () => {
  activeCell.value = clampCell(activeCell.value.row, activeCell.value.column);
});

const scrollPractitioners = (direction) => {
  const column = scroller.value?.querySelector(".header-cell");
  scroller.value?.scrollBy({ left: direction * 2 * column.offsetWidth });
};

// A computed changes only at slot boundaries, so the minute tick does not re-render every cell.
// Rows wrap past midnight, so past-ness compares timestamps, not row order.
const firstFutureTimestamp = computed(() => {
  let first = Infinity;
  for (const { timestamp } of slots.value)
    if (timestamp >= nowTime.value && timestamp < first) first = timestamp;
  return first;
});

const currentSlotIndex = computed(() => {
  const slotLength = dateStore.slotDuration * 60_000;
  return slots.value.findIndex(
    (slot) =>
      nowTime.value >= slot.timestamp &&
      nowTime.value < slot.timestamp + slotLength
  );
});

const scrollToCurrentSlot = () => {
  nextTick(() => {
    const row = currentSlotIndex.value;
    if (row < 0) return;
    activeCell.value = { row, column: activeCell.value.column };
    grid.value
      ?.querySelector(`[data-time-row="${row}"]`)
      ?.scrollIntoView({ block: "start" });
  });
};

const slotsPerHour = computed(() => Math.round(60 / dateStore.slotDuration));

function jumpToNow({ column }) {
  return currentSlotIndex.value < 0 ? null : [currentSlotIndex.value, column];
}

const keyTargets = {
  ArrowUp: ({ row, column }) => [row - 1, column],
  ArrowDown: ({ row, column }) => [row + 1, column],
  ArrowLeft: ({ row, column }) => [row, column - 1],
  ArrowRight: ({ row, column }) => [row, column + 1],
  PageUp: ({ row, column }) => [row - slotsPerHour.value, column],
  PageDown: ({ row, column }) => [row + slotsPerHour.value, column],
  Home: ({ row }) => [row, 0],
  End: ({ row }) => [row, practitioners.value.length - 1],
  t: jumpToNow,
  T: jumpToNow,
};

const onGridKeydown = (event) => {
  const target = keyTargets[event.key];
  if (!target || event.ctrlKey || event.metaKey || event.altKey) return;
  const position = target(activeCell.value);
  if (!position) return;
  event.preventDefault();
  focusCell(...position);
};

const clampCell = (row, column) => {
  const lastRow = slots.value.length - 1;
  const lastColumn = practitioners.value.length - 1;
  return {
    row: clamp(row, 0, Math.max(lastRow, 0)),
    column: clamp(column, 0, Math.max(lastColumn, 0)),
  };
};

const onCellFocus = (event) => {
  const { row, column } = event.target.dataset;
  if (row === undefined) return;
  if (activeCell.value.row === +row && activeCell.value.column === +column)
    return;
  activeCell.value = { row: +row, column: +column };
};

const focusCell = (row, column) => {
  activeCell.value = clampCell(row, column);
  nextTick(() => {
    const { row, column } = activeCell.value;
    const cell = grid.value?.querySelector(
      `[data-row="${row}"][data-column="${column}"]`
    );
    cell?.focus({ preventScroll: true });
    cell?.scrollIntoView({ block: "nearest", inline: "nearest" });
  });
};

// One shared empty list keeps the prop stable, so empty cells skip re-rendering.
const NO_APPOINTMENTS = Object.freeze([]);

const getAppointments = (slotTime, practitionerName) =>
  appointmentStore.appointmentsBySlot.get(slotTime)?.get(practitionerName) ??
  NO_APPOINTMENTS;

// Date navigation functions
const goToPreviousDay = () => {
  dateStore.goToPreviousDay();
};

const goToNextDay = () => {
  dateStore.goToNextDay();
};

// The server lists companies from user permissions, so no Company read access is needed.
const fetchUserCompanies = async () => {
  companyError.value = null;
  try {
    const {
      companies: permitted,
      default_company,
      slot_durations,
    } = await call("hms_tz.api.appointment.get_user_companies");
    companies.value = permitted;
    slotDurations.value = slot_durations;
    if (!default_company) {
      companyError.value = "No company is permitted for your user.";
    } else if (!selectedCompany.value) {
      selectedCompany.value = default_company;
    }
  } catch (error) {
    companyError.value = serverErrorText(error);
  }
};

const retryLoad = () =>
  companyError.value ? fetchUserCompanies() : loadDay();

// Any save on this company and date reloads the day, also one from the same user in another tab or
// on another computer. maxWait keeps a steady stream of saves from delaying the reload forever.
const reloadAppointments = useDebounceFn(
  () =>
    appointmentStore.fetchAppointments(
      selectedCompany.value,
      dateStore.selectedDate
    ),
  500,
  { maxWait: 2000 }
);

// Every open page gets the event at the same moment, so each waits a random time to spread the reloads.
const RELOAD_SPREAD_MS = 2000;

const onAppointmentUpdate = ({ company, appointment_date }) => {
  if (
    company === selectedCompany.value &&
    appointment_date === dateStore.selectedDate
  )
    setTimeout(reloadAppointments, Math.random() * RELOAD_SPREAD_MS);
};

// Rooms are lost on reconnect, so subscribe on every connect.
const subscribeToAppointments = () =>
  socket?.emit("doctype_subscribe", "Patient Appointment");

// Event handlers
const createAppointment = (timeSlot, practitioner) => {
  // Immediate state update for fast dialog opening
  selectedTimeSlot.value = timeSlot;
  selectedPractitioner.value = practitioner;
  dialogMode.value = "create";
  selectedAppointmentData.value = {};

  // Use nextTick for immediate UI update
  nextTick(() => {
    showAppointmentDialog.value = true;
  });
};

const viewAppointment = (appointment) => {
  selectedAppointmentData.value = appointment;
  dialogMode.value = "view";
  showAppointmentDialog.value = true;
};

// A search result sends ?appointment=&company=&date=; the grid moves there and shows it once the day loads.
const openAppointmentFromSearch = async ({ appointment, company, date }) => {
  router.replace({ query: {} });
  selectedCompany.value = company;
  dateStore.setSelectedDate(date);
  const found = await until(() =>
    appointmentStore.appointments.find(({ name }) => name === appointment)
  ).toBeTruthy({ timeout: 15_000 });
  if (found) viewAppointment(found);
  else notifications.error.generic(`Appointment ${appointment} did not load`);
};

watch(
  () => route.query.appointment,
  (appointment) => appointment && openAppointmentFromSearch(route.query),
  { immediate: true }
);

const closeAppointmentDialog = () => {
  showAppointmentDialog.value = false;
  selectedTimeSlot.value = "";
  selectedPractitioner.value = null;
  selectedAppointmentData.value = {};
  dialogMode.value = "create";
};

const refreshData = async () => {
  await loadDay();
  if (!loadErrorMessage.value) notifications.success.dataRefreshed();
};

const handleAppointmentCreated = () =>
  appointmentStore.fetchAppointments(
    selectedCompany.value,
    dateStore.selectedDate
  );

const handleModeChanged = (newMode, appointmentData) => {
  // Update dialog mode and appointment data
  dialogMode.value = newMode;
  if (appointmentData) {
    selectedAppointmentData.value = appointmentData;
  }
};

const handleEditAppointment = () => {
  // Switch from view mode to edit mode
  dialogMode.value = "edit";
};
</script>

<style scoped>
