  --time-column-width: 96px;
  --column-width: 144px;
  --column-gap: 8px;
  --row-height: 80px;
  --header-height: 96px;
  flex: 1;
  min-height: 0;
  overflow: auto;
  background-color: white;
  border-top: 1px solid #d1d5db;
