  scroll-padding-left: calc(var(--time-column-width) + var(--column-gap));
}

/* Each track holds its own gutter so sticky cells cover it when cards scroll under. */
.appointment-grid {
  display: grid;
  grid-template-columns:
    calc(var(--time-column-width) + var(--column-gap))
    repeat(var(--columns), calc(var(--column-width) + var(--column-gap)));
  grid-template-rows: var(--header-height);
  grid-auto-rows: var(--row-height);
  width: max-content;
  min-width: 100%;
}

.corner-cell,
.header-cell,
.time-cell {
  position: sticky;
  background-color: var(--sticky-background);
}

.corner-cell,
.header-cell {
  --sticky-background: white;
  top: 0;
  z-index: 2;
  border-bottom: 2px solid #e5e7eb;
}

.corner-cell,
.time-cell {
  --sticky-background: #f9fafb;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-right: 1px solid #d1d5db;
}

.corner-cell {
  z-index: 3;
}

.header-cell {
  display: flex;
  padding-right: var(--column-gap);
}

.empty-header {
  justify-content: center;
  text-align: center;
}

.time-cell {
  grid-column: 1;
  z-index: 1;
  border-bottom: 1px solid #e5e7eb;
  text-align: center;
}

.time-cell.current-time {
  --sticky-background: #fecaca;
  color: #b91c1c;
  box-shadow: inset 3px 0 0 #ef4444;
}

@media (max-width: 768px) {
  .appointment-grid-container {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }

  .grid-scroller {
    --time-column-width: 80px;
    --column-width: 128px;
  }
}

@media (max-width: 640px) {
  .appointment-grid-container .px-6 {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .appointment-grid-container .py-4 {
    padding-top: 0.75rem;
    padding-bottom: 0.75rem;
  }
}

@media (prefers-contrast: high) {
  .time-cell {
    border-color: #9ca3af;
  }
}
</style>
